!function(){const e=new URLSearchParams(location.search).get("id"),n=window.OasisAuth.findReserva(e),a=document.getElementById("rBody");if(!n)return document.getElementById("rTitle").textContent="Reserva no encontrada",void(a.innerHTML='<p class="lede">Este enlace no corresponde a una reserva guardada en este navegador.</p>');document.getElementById("rTitle").textContent=n.vehiculo,a.innerHTML=`<div class="reserva-card">\n    <div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:1rem">\n      <p class="eyebrow">${n.id}</p><span class="reserva-estado">${n.status}</span>\n    </div>\n    <div class="reserva-grid">\n      <div><span style="font-size:.7rem;color:var(--muted)">CLIENTE</span><b style="font-family:var(--font-body);font-size:1rem">${n.nombre}</b></div>\n      <div><span style="font-size:.7rem;color:var(--muted)">RECOGIDA</span><b>${n.fechaRecogida||"—"}</b></div>\n      <div><span style="font-size:.7rem;color:var(--muted)">REGRESO</span><b>${n.fechaRegreso||"—"}</b></div>\n      <div><span style="font-size:.7rem;color:var(--muted)">LUGAR</span><b style="font-family:var(--font-body);font-size:.95rem">${n.pickup||"—"}</b></div>\n    </div>\n  </div>`}();